17	const PROCESSING_FEE = 5;
18	const SWORD_BASE_PREMIUM = 100;
19	const FIRST_INSURANCE_SURCHARGE = 0.1;
20	
21	const roundUpInFavourOfMHPCO = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
22	
23	const quotePremium = (step: QuoteStep): number => {
24	  const base = step.items.length * SWORD_BASE_PREMIUM;
25	  return roundUpInFavourOfMHPCO(base * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
26	};
27	
28	export const runScenario = (scenario: Scenario): ScenarioResults => ({
29	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
30	});
